import crypto from "node:crypto";
// Authenticity tags: T1-<serial>-<signature>. The signature is an HMAC of the serial with a
// server-only secret, so valid codes can't be guessed or generated by counterfeiters.
const secret = () => process.env.TAG_SECRET || "dev-tag-secret-change-me";
const ALPH = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
const enc = (buf: Buffer, n: number) => Array.from(buf).slice(0, n).map((b) => ALPH[b % ALPH.length]).join("");
const sign = (serial: string) => enc(crypto.createHmac("sha256", secret()).update(serial).digest(), 8);

export function mintCode(): string {
  const serial = enc(crypto.randomBytes(8), 8);
  return `T1-${serial}-${sign(serial)}`;
}
export function normalizeCode(input: string): string {
  let s = input.trim();
  const m = s.match(/code=([A-Za-z0-9-]+)/);
  if (m) s = m[1];
  return s.toUpperCase();
}
export function signatureValid(code: string): boolean {
  const m = code.match(/^T1-([A-Z0-9]{8})-([A-Z0-9]{8})$/);
  if (!m) return false;
  const a = Buffer.from(sign(m[1])), b = Buffer.from(m[2]);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}
